# 1) 找最近 50 条登录失败并看来源 IP
Get-WinEvent -FilterHashtable @{LogName='Security';Id=4625} -MaxEvents 50 |
  ForEach-Object { $_.Properties[19].Value } | Group-Object | Sort-Object Count -Descending

# 2) 服务崩溃巡检（今天）
Get-WinEvent -FilterHashtable @{LogName='System';Id=7031,7034;StartTime=(Get-Date).Date} |
  Select-Object TimeCreated, Message -First 20

# 3) 计划任务巡检（上次结果非 0 的任务）
Get-ScheduledTask | ForEach-Object {
  $i = $_ | Get-ScheduledTaskInfo
  if ($i.LastTaskResult -ne 0 -and $i.LastRunTime -gt (Get-Date).AddDays(-1)) {
    [pscustomobject]@{Task=$_.TaskName; Last=$i.LastRunTime; Result=$i.LastTaskResult}
  }
}

# 许可/维保到期表巡检：30 天内到期的项输出告警
Import-Csv .\license.csv | ForEach-Object {
  $days = ([datetime]$_.Expiry - (Get-Date)).Days
  if ($days -le 30) { "{0}  {1}  剩余 {2} 天" -f $_.Name, $_.Expiry, $days }
}
